func struct_injection_interface_001_T(__taint_src string) {
	// 创建 IctestImpl 实例
	testSvc := &IctestImpl{}

	// 将业务实现注入到 IctestAPI 中
	testAPI := NewIctestAPI(testSvc)

	// 调用接口方法，返回的数据即为污点源，直接传入 sink
	result, _ := testAPI.GetTest(__taint_src)
	__taint_sink(result)
}

